    private void render(){
        try {
            try { rememberScroll(); } catch (Throwable ignored) {}
            try { cancelUiTasks(); } catch (Throwable ignored) {}
            try{YoruApp.app().focusNow(tab==1?"catalog":tab==2?"library":tab==3?"downloads":tab==4?"calendar":"home");}catch(Throwable ignored){}
            sourceView=false;historyView=false;generation++;loading=false;
            try { navigation(); } catch (Throwable ignored) {}
            if(profileView){
                try {
                    content.removeAllViews();
                    content.addView(new ProfileScreen(this,this::profileAction),new FrameLayout.LayoutParams(-1,-1));
                } catch (Throwable ignored) {}
                try { restoreScroll(); } catch (Throwable ignored) {}
                renderedTab=tab;renderedProfileView=profileView;return;
            }
            String key=""; try { key=screenKey(tab); } catch (Throwable ignored) { key="tab:"+tab; }
            if(screenCache[tab]!=null&&key.equals(screenKeys[tab])){
                try { content.removeAllViews(); } catch (Throwable ignored) {}
                try { attach(screenCache[tab]); } catch (Throwable ignored) {}
                if(tab==4&&calendarScreen!=null) try { calendarScreen.quickShow(); } catch (Throwable ignored) {}
                try { restoreScroll(); } catch (Throwable ignored) {}
                renderedTab=tab;renderedProfileView=profileView;return;
            }
            try { content.removeAllViews(); } catch (Throwable ignored) {}
            try {
                if(tab==0){if(HentaiEngine.isHenta())catalogue();else home();}
                else if(tab==1)catalogue();
                else if(tab==2)library(false);
                else if(tab==3)screen("Загрузки",()->new DownloadsScreen(this));
                else if(tab==4)screen("Календарь",this::calendarView);
            } catch (Throwable t) {
                try {
                    LinearLayout col=Ui.column(this);
                    col.setPadding(Ui.dp(this,18),Ui.dp(this,28),Ui.dp(this,18),Ui.dp(this,18));
                    col.addView(Ui.text(this,"Ошибка раздела",20,Ui.TEXT,true));
                    Ui.space(col,10);
                    String msg=""; try { msg=t.getMessage(); } catch (Throwable ignored) {}
                    col.addView(Ui.text(this,"Раздел восстановлен: "+msg,12,Ui.MUTED,false));
                    Ui.space(col,12);
                    col.addView(Ui.button(this,"Повторить",true,this::render));
                    content.addView(col,new FrameLayout.LayoutParams(-1,-1));
                } catch (Throwable ignored) {}
            }
            try { capture(tab,key); } catch (Throwable ignored) {}
            try { restoreScroll(); } catch (Throwable ignored) {}
            renderedTab=tab;renderedProfileView=profileView;
        } catch (Throwable t) {
            try {
                content.removeAllViews();
                LinearLayout col=Ui.column(this);
                col.addView(Ui.text(this,"Критическая ошибка",20,Ui.TEXT,true));
                col.addView(Ui.button(this,"На главную",true,()->{tab=0;render();}));
                content.addView(col,new FrameLayout.LayoutParams(-1,-1));
            } catch (Throwable ignored) {}
        }
    }

