    private void bindHero(Anime hero){if(hero==null||heroBg==null||heroTitle==null)return;heroTitle.setText(YoruBrain.title(hero));String meta=hero.year>0?String.valueOf(hero.year):"";if(!hero.genres.isEmpty())meta+=(meta.isEmpty()?"":" · ")+hero.genres.get(0);if(hero.score>0)meta+=(meta.isEmpty()?"":" · ")+String.format(Locale.US,"★ %.1f",hero.score);String eps=hero.episodesLine();if(!eps.isEmpty())meta+=(meta.isEmpty()?"":" · ")+eps;heroMeta.setText(meta);String desc=hero.description==null?"":hero.description.trim();if(desc.length()>150)desc=desc.substring(0,150).trim()+"…";if(desc.isEmpty())desc="Герой дня";heroDesc.setText(desc);YoruApp.app().images.load(heroBg,hero);}
    private void fetchHero(){if(heroBg==null)return;homeJobStart();final int gen=generation;uiTask(()->{try{ApiRepository.Filter f=new ApiRepository.Filter();f.sort="RATING_DESC";Anime.Page p=YoruApp.app().api.catalog("shikimori","",1,f);ArrayList<Anime> items=new ArrayList<>();for(Anime a:p.items)if(Anime.valid(a))items.add(a);if(items.isEmpty()){YoruApp.app().main.post(()->homeJobDone());return;}int stamp=0;try{stamp=YoruApp.app().store.todayStamp();}catch(Exception ignored){}Anime pick=items.get(Math.abs(stamp)%items.size());Anime hero=Anime.from(pick.json());hero.source="yoru";int mid=pick.malId>0?pick.malId:parseInt(pick.id);hero.id=String.valueOf(Math.max(1,mid));hero.malId=Math.max(0,mid);try{YoruApp.app().store.saveDailyHero(hero);YoruApp.app().api.prefetchEpisodeList(hero);}catch(Exception ignored){}YoruApp.app().main.post(()->{homeJobDone();if(gen==generation&&tab==0&&!isFinishing()&&heroBg!=null){heroCurrent=hero;bindHero(hero);heroBg.setAlpha(.25f);heroBg.animate().alpha(1f).setDuration(420).setInterpolator(new DecelerateInterpolator()).start();}});}catch(Exception e){YoruApp.app().main.post(()->homeJobDone());}});}
    private void recoBlock(LinearLayout col){JSONArray genres=YoruApp.app().store.stats().optJSONArray("genres");String topGenre=genres==null?"":genres.optString(0,"");recoGenre=genreIdFor(topGenre);if(recoGenre.isEmpty())return;Ui.space(col,25);section(col,"Рекомендации для вас","Каталог",()->{tab=1;render();});col.addView(Ui.text(this,"Подобрано по вашим жанрам · обновляется каждый день",11,Ui.MUTED,false));Ui.space(col,10);recoHost=Ui.column(this);col.addView(recoHost);fetchReco();}
    private void fetchReco(){if(recoHost==null||recoGenre.isEmpty())return;homeJobStart();final int gen=generation;final LinearLayout host=recoHost;final String genre=recoGenre;int stamp=1;try{stamp=Math.abs(YoruApp.app().store.todayStamp())%4+1;}catch(Exception ignored){}final int page=stamp;uiTask(()->{try{ApiRepository.Filter f=new ApiRepository.Filter();f.sort="RATING_DESC";f.genre=genre;Anime.Page p=YoruApp.app().api.catalog("shikimori","",page,f);ArrayList<Anime> out=new ArrayList<>();for(Anime a:p.items)if(Anime.valid(a)){out.add(a);if(out.size()>=6)break;}YoruApp.app().main.post(()->{homeJobDone();if(gen==generation&&tab==0&&!isFinishing()&&!out.isEmpty()){renderCards(host,out);YoruApp.app().api.prefetchEpisodes(out,2);}});}catch(Exception e){YoruApp.app().main.post(()->homeJobDone());}});}
