    private void loadTopChunk(boolean first){if(topLoading||topDone||topHost==null)return;topLoading=true;final int gen=generation;final LinearLayout host=topHost;if(first)homeJobStart();uiTask(()->{try{ArrayList<Anime> chunk=new ArrayList<>();synchronized(topBuffer){chunk.addAll(topBuffer);topBuffer.clear();}while(chunk.size()<6&&!topDone){ApiRepository.Filter f=new ApiRepository.Filter();f.sort="RATING_DESC";Anime.Page p=YoruApp.app().api.catalog("shikimori","",topPage+1,f);topPage++;for(Anime a:p.items)if(Anime.valid(a))chunk.add(a);if(!p.more||p.items.isEmpty()||topPage>=12)topDone=true;}ArrayList<Anime> show=new ArrayList<>(chunk.subList(0,Math.min(6,chunk.size())));synchronized(topBuffer){for(int i=show.size();i<chunk.size();i++)topBuffer.add(chunk.get(i));}final boolean done=topDone&&topBuffer.isEmpty();YoruApp.app().main.post(()->{if(first)homeJobDone();topLoading=false;if(gen!=generation||tab!=0||isFinishing()||topHost==null||topHost!=host)return;if(!show.isEmpty()){if(first&&topSeedShown){topSeedShown=false;topHost.removeAllViews();}appendTopCards(topHost,show);}if(topFooter!=null){if(topHost.getChildCount()==0)topFooter.setText("Потяните вниз, чтобы обновить топ");else topFooter.setText(done?"Это весь топ на сегодня":"Листайте вниз · подгружаем по 6");}});}catch(Exception e){YoruApp.app().main.post(()->{if(first)homeJobDone();topLoading=false;if(gen!=generation||tab!=0||isFinishing()||topHost==null||topHost!=host)return;if(topFooter!=null)topFooter.setText(topHost.getChildCount()==0?"Потяните вниз, чтобы обновить топ":"Листайте вниз · подгружаем по 6");});}});}
