    private Anime historyAnime(String q){try{ArrayList<Anime> rows=localSuggestions(q);if(rows!=null&&!rows.isEmpty())return rows.get(0);}catch(Exception ignored){}return null;}
    private ArrayList<Anime> localCatalogPreview(String source,ApiRepository.Filter f){ArrayList<Anime> out=new ArrayList<>();for(Anime a:YoruApp.app().api.seed())if(Anime.valid(a)&&YoruBrain.visible(a)&&localFilter(a,f))out.add(a);out.sort((a,b)->localCompare(a,b,f));return new ArrayList<>(out.subList(0,Math.min(24,out.size())));}
    private boolean localFilter(Anime a,ApiRepository.Filter f){if(f==null)return true;if(!f.year.isEmpty()&&a.year!=parseInt(f.year))return false;if(!f.type.isEmpty()){String t=(a.type==null?"":a.type).toLowerCase(Locale.ROOT);if(f.type.equals("MOVIE")&&!t.contains("movie")&&!t.contains("фильм"))return false;if(f.type.equals("TV")&&!t.contains("tv")&&!t.contains("тв")&&!t.contains("сериал"))return false;if(f.type.equals("ONA")&&!t.contains("ona"))return false;if(f.type.equals("OVA")&&!t.contains("ova"))return false;if(f.type.equals("SPECIAL")&&!t.contains("спешл")&&!t.contains("special"))return false;}if(!f.status.isEmpty()){String st=a.statusLabel().toLowerCase(Locale.ROOT);if(f.status.equals("ongoing")&&!st.contains("онго"))return false;if(f.status.equals("released")&&!st.contains("закон"))return false;if(f.status.equals("anons")&&!st.contains("анонс"))return false;}if(!f.genre.isEmpty()&&!genreMatch(a,f.genre))return false;return true;}
    private boolean genreMatch(Anime a,String id){if(a==null||a.genres.isEmpty())return false;String g=String.join(" ",a.genres).toLowerCase(Locale.ROOT).replace('ё','е');String[][] table={{"1","экшен","action"},{"2","приключ","adventure"},{"3","машин","cars"},{"4","комед","comedy"},{"5","безумие","dementia"},{"6","демон","demons"},{"7","детектив","mystery"},{"8","драма","drama"},{"9","этти","ecchi"},{"10","фэнт","fantasy"},{"11","игр","game"},{"12","хентай","hentai"},{"13","историч","historical"},{"14","ужас","хоррор","horror"},{"15","детск","kids"},{"16","маги","magic"},{"17","боев","martial"},{"18","меха","mecha"},{"19","музык","music"},{"20","пароди","parody"},{"21","самурай","samurai"},{"22","роман","romance"},{"23","школ","school"},{"24","фантаст","sci-fi","scifi"},{"25","седз","shoujo"},{"26","дзе-ай","дзе ай","shoujo ai"},{"27","сенен","shounen","сенэн"},{"28","нен-ай","нен ай","shounen ai"},{"29","космос","space"},{"30","спорт","sport"},{"31","супер","super"},{"32","вампир","vampire"},{"33","яой","yaoi"},{"34","юри","yuri"},{"35","гарем","harem"},{"36","повсед","слайс","slice"},{"37","сверхъестеств","supernatural"},{"38","военн","military"},{"39","полиц","police"},{"40","психолог","psychological"},{"41","триллер","thriller"},{"42","сэйнэн","сэйнен","seinen"},{"43","дзесей","дзёсей","josei"},{"539","эротик","erotica"},{"541","работ","work"},{"543","гурман","gourmet"}};for(String[] row:table){if(!row[0].equals(id))continue;boolean hit=false;for(int i=1;i<row.length;i++)if(g.contains(row[i])){hit=true;break;}if(!hit)return false;if(id.equals("25")||id.equals("27"))return !g.contains("-ай")&&!g.contains(" ай");return true;}return false;}
    private int localCompare(Anime a,Anime b,ApiRepository.Filter f){if(f!=null&&"NAME".equals(f.sort))return YoruBrain.title(a).compareToIgnoreCase(YoruBrain.title(b));return Integer.compare(localSortScore(b,f),localSortScore(a,f));}
    private int localSortScore(Anime a,ApiRepository.Filter f){String sort=f==null?"":f.sort;if("NAME".equals(sort))return -YoruBrain.title(a).toLowerCase(Locale.ROOT).hashCode();int r=0;if("YEAR_DESC".equals(sort))r+=Math.max(0,a.year)*100;else r+=(int)Math.round(a.score*1000);if(a.ongoing())r+=80;return r;}
    private int parseInt(String v){try{return Integer.parseInt(v);}catch(Exception e){return 0;}}
    private ArrayList<Anime> localSuggestions(String q){LinkedHashMap<String,Anime> found=new LinkedHashMap<>();String needle=ApiRepository.plainName(q);if(needle.length()<1)return new ArrayList<>();ArrayList<Anime> pool=new ArrayList<>();pool.addAll(YoruApp.app().store.recent());pool.addAll(YoruApp.app().store.favorites());pool.addAll(YoruApp.app().api.seed());for(Anime a:pool){if(!Anime.valid(a)||!YoruBrain.visible(a)||found.containsKey(a.key()))continue;String hay=ApiRepository.plainName(a.title+" "+a.original+" "+a.alias+" "+String.join(" ",a.genres)+" "+YoruApp.app().store.note(a)+" "+YoruApp.app().store.tags(a));if(hay.contains(needle))found.put(a.key(),a);}ArrayList<Anime> out=new ArrayList<>(found.values());out.sort((a,b)->Integer.compare(searchRank(b,needle),searchRank(a,needle)));return new ArrayList<>(out.subList(0,Math.min(10,out.size())));}
    private int searchRank(Anime a,String needle){String title=ApiRepository.plainName(a.title),orig=ApiRepository.plainName(a.original),all=ApiRepository.plainName(a.title+" "+a.original+" "+a.alias);int r=0;if(title.equals(needle)||orig.equals(needle))r+=10000;else if(title.startsWith(needle)||orig.startsWith(needle))r+=6500;else if(all.contains(needle))r+=3000;r+=Math.max(0,Math.min(3000,a.year));if(a.ongoing())r+=200;if(a.score>0)r+=(int)(a.score*20);return r;}
