    private void loadCatalog(boolean reset){if(adapter==null||summary==null)return;if(catalogRetry!=null)handler.removeCallbacks(catalogRetry);if(reset&&catalogFuture!=null&&!catalogFuture.isDone()){catalogFuture.cancel(true);loading=false;}if(loading&&!reset)return;String q=query==null?"":query.trim().replaceAll("\\s+"," ");query=q;String source=selectedSource;ApiRepository.Filter f=filter;if(screenCache[1]!=null)screenKeys[1]=screenKey(1);if(reset){generation++;pageNumber=0;catalog.clear();more=false;if(q.length()>=1)catalog.addAll(localSuggestions(q));else catalog.addAll(localCatalogPreview(source,filter));adapter.notifyDataSetChanged();}loading=true;int gen=generation,requested=pageNumber+1;summary.setOnClickListener(null);summary.setText(reset?(catalog.isEmpty()?(HentaiEngine.isHenta()?"Собираем рабочие источники…":""):""):"Ещё аниме…");catalogFuture=uiTask(()->{try{if(Thread.currentThread().isInterrupted())return;Anime.Page p=YoruApp.app().api.catalog(source,q,requested,f);if(Thread.currentThread().isInterrupted())return;YoruApp.app().main.post(()->{if(gen!=generation||tab!=1||isFinishing())return;loading=false;lastCatalogAt=System.currentTimeMillis();stopCatalogSwipe();pageNumber=requested;more=p.more;HashSet<String> ids=new HashSet<>();if(reset&&!p.items.isEmpty())catalog.clear();for(Anime a:catalog)ids.add(a.key());for(Anime a:p.items)if(YoruBrain.visible(a)&&ids.add(a.key()))catalog.add(a);adapter.notifyDataSetChanged();String prefix=p.total>=0?"Найдено: "+p.total+" · ":q.isEmpty()&&YoruApp.app().api.countOf(source)>0?"В базе: "+YoruApp.app().api.countOf(source)+" · ":"";if(p.note!=null&&!p.note.isEmpty())prefix=p.note+" · "+prefix;summary.setText(prefix+"Показано: "+catalog.size()+(p.more?" · листайте дальше":""));if(catalog.isEmpty())summary.setText(p.note!=null&&!p.note.isEmpty()?p.note:(q.isEmpty()?"Пока пусто Нажмите для повтора":"Ничего не найдено Попробуйте другое название"));});}catch(Exception e){YoruApp.app().main.post(()->{if(gen!=generation||tab!=1||isFinishing())return;loading=false;stopCatalogSwipe();more=false;if(catalog.isEmpty()&&source.equals("anilibria")&&q.isEmpty())catalog.addAll(YoruApp.app().api.seed());adapter.notifyDataSetChanged();if(catalog.isEmpty()){summary.setText("Не удалось подключиться Нажмите для повтора");summary.setOnClickListener(v->loadCatalog(true));}else{summary.setText("Показано: "+catalog.size());summary.setOnClickListener(null);scheduleCatalogRetry();}});}});if(catalogFuture.isCancelled()){loading=false;stopCatalogSwipe();summary.setText("Очередь занята Нажмите для повтора");summary.setOnClickListener(v->loadCatalog(true));}}
