    private void silentCatalogRefresh(){if(adapter==null||summary==null||loading)return;if(catalogRetry!=null)handler.removeCallbacks(catalogRetry);loading=true;final int gen=generation;final String q=query==null?"":query.trim();final String source=selectedSource;final ApiRepository.Filter f=filter;catalogFuture=uiTask(()->{try{Anime.Page p=YoruApp.app().api.catalog(source,q,1,f);if(Thread.currentThread().isInterrupted())return;YoruApp.app().main.post(()->{if(gen!=generation||tab!=1||isFinishing())return;loading=false;lastCatalogAt=System.currentTimeMillis();stopCatalogSwipe();pageNumber=1;more=p.more;HashSet<String> ids=new HashSet<>();ArrayList<Anime> fresh=new ArrayList<>();for(Anime a:p.items)if(YoruBrain.visible(a)&&ids.add(a.key()))fresh.add(a);if(!fresh.isEmpty()){catalog.clear();catalog.addAll(fresh);adapter.notifyDataSetChanged();}summary.setOnClickListener(null);summary.setText((p.total>=0?"Найдено: "+p.total+" · ":"")+"Показано: "+catalog.size()+(more?" · листайте дальше":""));});}catch(Exception e){YoruApp.app().main.post(()->{if(gen!=generation||tab!=1||isFinishing())return;loading=false;stopCatalogSwipe();scheduleCatalogRetry();});}});}
